//! Real-file checks for the Windows-codec path (HEIC, RAW, JPEG XR). They run through whatever
//! codecs this machine has installed, so each test first asks Luma whether its family is
//! working here and says so loudly if it has to skip; a skipped family is "not exercised on this
//! machine", never "passed". Fixtures are generated by Luma's own scripts (see
//! scripts/make_codec_fixtures.py) from colour arithmetic: no camera or third-party content.
use luma::{
    decode::{self, Cancel, Photo},
    wic::{self, Availability, Family},
};
use std::{
    io::{Cursor, Read},
    path::{Path, PathBuf},
};

fn fixture(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("fixtures/windows-codecs")
        .join(name)
}

/// True when this machine's codec for `family` decoded its self-check sample just now.
fn working(family: Family) -> bool {
    let status = wic::status()
        .into_iter()
        .find(|s| s.family == family)
        .expect("family listed");
    match status.availability {
        Availability::Working { .. } => true,
        other => {
            eprintln!("SKIPPED {family:?}: not exercised on this machine ({other:?})");
            false
        }
    }
}

const RED: [u8; 3] = [230, 30, 30];
const GREEN: [u8; 3] = [30, 200, 60];
const YELLOW: [u8; 3] = [240, 220, 40];
const BLUE: [u8; 3] = [40, 70, 230];

/// Name the reference colour a pixel is closest to. Codecs are lossy and RAW goes through
/// white balance and tone curves, so exact values are not expected; the four references are
/// far enough apart that the nearest one is unambiguous.
fn classify(px: [u8; 3]) -> char {
    let dist = |c: [u8; 3]| -> i32 {
        (0..3)
            .map(|i| (i32::from(px[i]) - i32::from(c[i])).pow(2))
            .sum()
    };
    [('R', RED), ('G', GREEN), ('Y', YELLOW), ('B', BLUE)]
        .into_iter()
        .min_by_key(|(_, c)| dist(*c))
        .map(|(name, _)| name)
        .unwrap()
}

/// Corners TL, TR, BR, BL sampled 14 px in, clear of the white tick and the colour boundaries.
fn corners(p: &Photo) -> String {
    let (w, h) = (p.width as usize, p.height as usize);
    let at = |x: usize, y: usize| {
        let i = (y * w + x) * 4;
        let px = &p.frames[0].rgba[i..i + 3];
        classify([px[0], px[1], px[2]])
    };
    let m = 14;
    [
        at(m, m),
        at(w - 1 - m, m),
        at(w - 1 - m, h - 1 - m),
        at(m, h - 1 - m),
    ]
    .iter()
    .collect()
}

fn decode_fixture(name: &str) -> Photo {
    decode::decode(&fixture(name), &Cancel::never()).unwrap_or_else(|e| panic!("{name}: {e}"))
}

#[test]
fn heic_decodes_and_every_container_transform_matches_an_independent_corner_table() {
    if !working(Family::Heif) {
        return;
    }
    // Stored picture, corners TL TR BR BL = R G Y B. Expected displayed corners per transform,
    // worked out by hand and not derived from Luma's code. irot is anticlockwise quarter turns.
    // For imir, the Windows HEIF decoder (HEIF Image Extensions 1.2.48) exchanges top and bottom
    // for value 0 and left and right for value 1. My first expectation, the opposite, was wrong
    // and the pixels corrected it. This agrees with libavif's avifImageMirror documentation,
    // which cites ISO/IEC 23008-12:2022: axis 0 exchanges top and bottom, axis 1 left and right
    // (https://github.com/AOMediaCodec/libavif/blob/main/include/avif/avif.h).
    // irot is applied before imir (the order the properties are listed in the file).
    let cases: [(&str, (u32, u32), &str); 7] = [
        ("pattern.heic", (96, 64), "RGYB"),
        ("irot1.heic", (64, 96), "GYBR"),
        ("irot2.heic", (96, 64), "YBRG"),
        ("irot3.heic", (64, 96), "BRGY"),
        ("imir0.heic", (96, 64), "BYGR"),
        ("imir1.heic", (96, 64), "GRBY"),
        // irot1 gives G Y B R; exchanging top and bottom then gives R B Y G.
        ("irot1-imir0.heic", (64, 96), "RBYG"),
    ];
    // Every case is checked and reported together, so one wrong transform cannot hide another.
    let mut table = Vec::new();
    let mut wrong = Vec::new();
    for (name, dims, expected) in cases {
        let p = decode_fixture(name);
        let got = corners(&p);
        table.push(format!(
            "{name:18} {}x{} corners {got} (expected {expected})",
            p.width, p.height
        ));
        if (p.width, p.height) != dims || got != expected {
            wrong.push(name);
        }
        assert!(p.format.starts_with("HEIC"), "{name}: {}", p.format);
        assert!(p.decoder.starts_with("Windows codec:"), "{}", p.decoder);
        assert_eq!(p.byte_len(), (p.width * p.height * 4) as usize);
        // No double rotation: Luma's own guard must not have fired for a decoder that rotates.
        assert!(
            !p.warnings
                .iter()
                .any(|w| w.contains("returned this HEIC unrotated")),
            "{name}: {:?}",
            p.warnings
        );
    }
    eprintln!("{}", table.join("\n"));
    assert!(
        wrong.is_empty(),
        "transform mismatches {wrong:?}:\n{}",
        table.join("\n")
    );
}

#[test]
fn jpeg_xr_decodes_with_the_right_colours() {
    if !working(Family::JpegXr) {
        return;
    }
    let p = decode_fixture("pattern.jxr");
    assert_eq!((p.width, p.height), (96, 64));
    assert_eq!(corners(&p), "RGYB");
    assert!(p.format.starts_with("JPEG XR"));
}

#[test]
fn a_dng_decodes_and_is_turned_upright_only_when_the_observed_decoder_read_it() {
    if !working(Family::Dng) {
        return;
    }
    let upright = decode_fixture("synthetic-cfa.dng");
    assert_eq!((upright.width, upright.height), (96, 64));
    assert_eq!(corners(&upright), "RGYB");
    assert_eq!(upright.applied_orientation, None);
    // Named from the file's DNGVersion tag, not from its extension.
    assert!(
        upright.format.starts_with("RAW (DNG)"),
        "{}",
        upright.format
    );
    eprintln!("DNG decoded by: {}", upright.decoder);

    // The same mosaic tagged EXIF orientation 6 (rotate 90 clockwise to view). Microsoft's Raw
    // Image Decoder, which Windows picked for this file on the development machine, returns it
    // at stored size, so Luma turns it: stored TL lands top-right. That is observed for that
    // decoder only. Any other decoder that reads it is shown as returned, with a warning.
    let turned = decode_fixture("synthetic-cfa-orient6.dng");
    eprintln!("orientation-6 DNG decoded by: {}", turned.decoder);
    if turned.decoder.contains("Microsoft Raw Image Decoder") {
        assert_eq!((turned.width, turned.height), (64, 96));
        assert_eq!(corners(&turned), "BRGY");
        assert_eq!(turned.applied_orientation, Some(6));
    } else {
        assert_eq!(turned.applied_orientation, None);
        assert!(
            turned
                .warnings
                .iter()
                .any(|w| w.contains("orientation tag 6")),
            "{:?}",
            turned.warnings
        );
    }
}

/// Camera RAW (CR2, NEF, ARW) has no sample here. This stands in for the nearest thing that can
/// be made without inventing a camera format: the same TIFF-structured file with its DNGVersion
/// tag renamed, saved as ".nef". Luma must not rotate it (it has no observation for it) and must
/// say so. If the codec refuses the altered file, nothing is asserted and the test says so.
#[test]
fn a_raw_that_is_not_a_dng_is_never_turned_by_luma_and_says_so() {
    if !working(Family::Dng) {
        return;
    }
    let mut bytes = std::fs::read(fixture("synthetic-cfa-orient6.dng")).unwrap();
    assert_eq!(&bytes[..4], b"II*\0");
    let ifd0 = u32::from_le_bytes(bytes[4..8].try_into().unwrap()) as usize;
    let count = u16::from_le_bytes(bytes[ifd0..ifd0 + 2].try_into().unwrap()) as usize;
    let mut renamed = false;
    for i in 0..count {
        let at = ifd0 + 2 + i * 12;
        if bytes[at..at + 2] == 0xC612u16.to_le_bytes() {
            bytes[at..at + 2].copy_from_slice(&0xC6FFu16.to_le_bytes());
            renamed = true;
        }
    }
    assert!(renamed, "the fixture has a DNGVersion entry");
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("pretend.nef");
    std::fs::write(&path, &bytes).unwrap();
    match decode::decode(&path, &Cancel::never()) {
        Err(e) => eprintln!("SKIPPED: the codec refuses a DNG without DNGVersion ({e})"),
        Ok(p) => {
            eprintln!("non-DNG RAW decoded by: {}", p.decoder);
            assert_eq!(p.applied_orientation, None);
            assert_eq!(
                (p.width, p.height),
                (96, 64),
                "shown as the codec returned it"
            );
            assert!(
                p.warnings.iter().any(|w| w.contains("orientation tag 6")),
                "{:?}",
                p.warnings
            );
            assert!(!p.format.starts_with("RAW (DNG)"), "{}", p.format);
        }
    }
}

#[test]
fn raw_exif_is_read_from_the_tiff_structure() {
    if !working(Family::Dng) {
        return;
    }
    let p = decode_fixture("synthetic-cfa.dng");
    let exif = p.exif.expect("EXIF from the DNG's own IFDs");
    assert_eq!(exif.make.as_deref(), Some("Version2 Test"));
    assert_eq!(exif.model.as_deref(), Some("Luma synthetic DNG"));
    assert_eq!(exif.iso, Some(200));
    assert_eq!(exif.exposure_time, Some((1, 125)));
    assert_eq!(exif.taken.as_deref(), Some("2026-10-09 14:03:22"));
    let rows = exif.rows();
    assert!(
        rows.iter()
            .any(|(k, v)| *k == "Exposure" && v == "1/125 s · f/2.8 · ISO 200"),
        "{rows:?}"
    );
}

#[test]
fn the_format_shown_comes_from_the_decoder_that_read_the_file_not_its_extension() {
    if !(working(Family::Heif) && working(Family::JpegXr) && working(Family::Dng)) {
        return;
    }
    let dir = tempfile::tempdir().unwrap();
    let copy = |from: &str, to: &str| {
        let path = dir.path().join(to);
        std::fs::copy(fixture(from), &path).unwrap();
        path
    };
    // (source fixture, name it is saved under, format Luma must report, expected corners)
    let cases = [
        ("pattern.heic", "mislabelled.jxr", "HEIC", "RGYB"),
        ("pattern.heic", "mislabelled.dng", "HEIC", "RGYB"),
        // A built-in extension with Windows-codec content falls back to Windows by content.
        ("pattern.heic", "mislabelled.jpg", "HEIC", "RGYB"),
        ("pattern.heic", "mislabelled.png", "HEIC", "RGYB"),
        ("pattern.jxr", "mislabelled.heic", "JPEG XR", "RGYB"),
        ("pattern.jxr", "mislabelled.nef", "JPEG XR", "RGYB"),
        // Container rotation still applies when the extension is wrong.
        ("irot1.heic", "mislabelled-rotated.jxr", "HEIC", "GYBR"),
        // DNG content under a HEIC name is still a DNG: recognised by its DNGVersion tag, and
        // orientation 6 is applied from its EXIF when the observed decoder read it.
        (
            "synthetic-cfa-orient6.dng",
            "mislabelled-raw.heic",
            "RAW (DNG)",
            "BRGY",
        ),
    ];
    for (source, saved_as, format, expected_corners) in cases {
        let p = decode::decode(&copy(source, saved_as), &Cancel::never())
            .unwrap_or_else(|e| panic!("{saved_as}: {e}"));
        assert!(
            p.format.starts_with(format),
            "{saved_as}: reported {:?}, expected {format}",
            p.format
        );
        assert!(
            p.format.ends_with("Windows codec"),
            "{saved_as}: {}",
            p.format
        );
        // A DNG tagged orientation 6 is turned only when the observed decoder read it; any other
        // decoder returns it as stored (RGYB) and says so, which is the honest outcome too.
        let observed = p.decoder.contains("Microsoft Raw Image Decoder");
        let expected_corners = if source == "synthetic-cfa-orient6.dng" && !observed {
            "RGYB"
        } else {
            expected_corners
        };
        assert_eq!(corners(&p), expected_corners, "{saved_as}");
    }
    // The error for a damaged file still names what the extension claims, but that is a message
    // about the file, kept apart from any format shown for a decoded one.
    let damaged = dir.path().join("damaged.jxr");
    std::fs::copy(fixture("truncated.heic"), &damaged).unwrap();
    assert!(decode::decode(&damaged, &Cancel::never()).is_err());
}

#[test]
fn damaged_and_misnamed_files_fail_with_a_message_and_never_panic() {
    for (name, word) in [("truncated.heic", "HEIF"), ("garbage.dng", "DNG")] {
        let message = decode::decode(&fixture(name), &Cancel::never()).unwrap_err();
        assert!(!message.is_empty(), "{name}");
        // Either the codec is missing here, or Windows reports a code for this damaged file.
        assert!(
            message.contains("0x") || message.contains("needs a Windows codec"),
            "{name}: {message}"
        );
        assert!(
            message.contains(word),
            "{name} should name {word}: {message}"
        );
    }
}

#[test]
fn the_pixel_budget_is_enforced_before_any_pixel_is_copied() {
    if !working(Family::JpegXr) {
        return;
    }
    // 17000 x 16 is only 272,000 pixels but exceeds the per-side limit; 6000 x 5000 is within
    // the side limit but 30 MP. Both must be refused on the dimensions Windows reports.
    for name in ["oversize-side.jxr", "oversize-pixels.jxr"] {
        let started = std::time::Instant::now();
        let message = decode::decode(&fixture(name), &Cancel::never()).unwrap_err();
        assert!(message.contains("safe decode limit"), "{name}: {message}");
        assert!(
            started.elapsed() < std::time::Duration::from_secs(2),
            "{name} was refused only after {:?}: it was decoded first",
            started.elapsed()
        );
    }
}

#[test]
fn a_cancelled_request_stops_before_the_codec_is_started() {
    use std::sync::{Arc, atomic::AtomicU64};
    let generation = Arc::new(AtomicU64::new(1));
    let cancel = Cancel::new(generation.clone(), 1);
    generation.store(2, std::sync::atomic::Ordering::Release);
    let error = decode::decode(&fixture("pattern.heic"), &cancel).unwrap_err();
    assert!(error.contains("Cancelled"), "{error}");
}

#[test]
fn status_reports_each_family_without_claiming_more_than_it_checked() {
    let statuses = wic::status();
    assert_eq!(statuses.len(), Family::ALL.len());
    for s in &statuses {
        eprintln!("{:?}: {:?}", s.family, s.availability);
        match (&s.family, &s.availability) {
            // JPEG XL has no self-check sample, so "Working" would be an unproven claim.
            (Family::JpegXl, Availability::Working { .. }) => {
                panic!("JPEG XL cannot be called Working without a sample")
            }
            // The only RAW sample is a DNG. That says nothing about CR2, NEF or ARW, so camera
            // RAW can be "found" but never "working".
            (Family::Raw, Availability::Working { .. }) => {
                panic!("camera RAW cannot be called Working without a camera sample")
            }
            // "Working" names the decoder that really decoded the sample: the same one that
            // decodes the DNG fixture, not merely the first decoder registered for DNG.
            (Family::Dng, Availability::Working { decoder }) => {
                let p = decode_fixture("synthetic-cfa.dng");
                assert_eq!(p.decoder, format!("Windows codec: {decoder}"));
            }
            (_, Availability::Failing { error, .. }) => assert!(!error.is_empty()),
            _ => {}
        }
    }
    // The registered list is real data from Windows: every entry has a name.
    let installed = wic::decoders().unwrap();
    assert!(!installed.is_empty());
    assert!(
        installed.iter().all(|d| !d.name.is_empty()),
        "{installed:?}"
    );
}

/// A reader that counts what is taken from it.
struct Counting<R> {
    inner: R,
    taken: u64,
}
impl<R: Read> Read for Counting<R> {
    fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        let n = self.inner.read(buf)?;
        self.taken += n as u64;
        Ok(n)
    }
}

#[test]
fn raw_exif_reads_a_bounded_prefix_not_the_whole_file() {
    // A real DNG (small EXIF at the front) followed by 6 MiB of sensor-like padding: 6+ MiB in
    // all, above the 4 MiB the EXIF parser accepts.
    let mut bytes = std::fs::read(fixture("synthetic-cfa.dng")).unwrap();
    bytes.resize(bytes.len() + 6 * 1024 * 1024, 0x5A);
    assert!(bytes.len() > 4 * 1024 * 1024);
    let mut reader = Counting {
        inner: Cursor::new(bytes),
        taken: 0,
    };
    let exif = wic::tiff_prefix_exif(&mut reader).expect("early EXIF is kept");
    assert_eq!(exif.make.as_deref(), Some("Version2 Test"));
    assert!(
        reader.taken <= wic::EXIF_PREFIX_BYTES,
        "read {} bytes, more than the {} byte prefix",
        reader.taken,
        wic::EXIF_PREFIX_BYTES
    );
    // Not a TIFF: nothing is parsed and nothing beyond the prefix is read either.
    let mut other = Counting {
        inner: Cursor::new(vec![0xFFu8; 8 * 1024 * 1024]),
        taken: 0,
    };
    assert!(wic::tiff_prefix_exif(&mut other).is_none());
    assert!(other.taken <= wic::EXIF_PREFIX_BYTES);
}

#[test]
fn originals_are_never_modified_by_decoding() {
    let dir = fixture("");
    let before: Vec<_> = std::fs::read_dir(&dir)
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| p.is_file())
        .map(|p| {
            let bytes = std::fs::read(&p).unwrap();
            let modified = std::fs::metadata(&p).unwrap().modified().unwrap();
            (p, bytes, modified)
        })
        .collect();
    for (path, ..) in &before {
        let _ = decode::decode(path, &Cancel::never());
    }
    for (path, bytes, modified) in &before {
        assert_eq!(&std::fs::read(path).unwrap(), bytes, "{}", path.display());
        assert_eq!(
            &std::fs::metadata(path).unwrap().modified().unwrap(),
            modified,
            "{} timestamp",
            path.display()
        );
    }
}
